export type AesopUpsellProps = Record<string, any>;

// Helper for particle randomness
const getParticles = (count: number, seed: string) => {
  return Array.from({ length: count }).map((_, i) => {
    const angle = random(`${seed}-angle-${i}`) * Math.PI * 2;
    const speed = 100 + random(`${seed}-speed-${i}`) * 250;
    const size = 2 + random(`${seed}-size-${i}`) * 5;
    const delay = random(`${seed}-delay-${i}`) * 30;
    return { angle, speed, size, delay };
  });
};

